// iso_reader_cluedo_menu_tb.sv - real-data reader+VM check of the Cluedo
// Menu/Title key behaviour (fixture bench/dvd/test_vobs/cluedo_menu_meta.hex,
// generated by tools/cluedo_fixture.py from the real ISO; reader and VM wired
// exactly as emu.sv wires them).
//
// Cluedo (AUS PAL) boot: FP {g5=0; g15=0; JumpTT 1} -> VTS1 title PGC1 PRE
// (GPRM5 dispatch, all false at boot) -> CallSS VMGM pgc2 -> the copyright /
// logos / intro chain (VMGM PGC2-5) -> PGC6 = the 13-button game menu.
//
// [A] MENU key during the copyright: the disc's authored VTSM Root (entry
//     0x83 EXISTS - PGCN 1) has PRE {g5 = 0; JumpVTS_TT 1}: the ROOT MENU IS
//     a restart-the-presentation trampoline (it even clears the game state).
//     A libdvdnav player's MENU button runs the same commands, so the
//     copyright replay on Menu is AUTHORED behaviour - assert our chain
//     matches it exactly: VTSM PGC1 -> title vts1/pgc1 -> VMGM PGC2.
//
// [B] TITLE key (B12, new) during the copyright: VMGM Title entry (0x82,
//     PGCN 1) -> PRE LinkPGCN 12 -> PGC12 dispatcher PRE
//     {g0=g15&0x1f; if (g0==0) LinkPGCN 6} -> PGC6 = the game menu DIRECTLY,
//     with no title-domain excursion and no copyright (PGC2) replay. This is
//     the real-remote "Top Menu" behaviour and the fast path into the game.
//
// Run: iverilog -g2012 -o /tmp/rcm dvd/dvd_iso_reader.sv dvd/dvd_vm.sv \
//        dvd/bcd_time_add.sv bench/dvd/iso_reader_cluedo_menu_tb.sv && vvp /tmp/rcm

`timescale 1ns/1ps

module iso_reader_cluedo_menu_tb;

    reg         clk = 0;
    reg         rst_n = 0;
    reg         start = 0;
    reg  [63:0] file_size = 64'd4487258112;   // real image size

    wire [31:0] sd_lba;
    wire        sd_rd;
    reg         sd_ack = 0;
    reg  [13:0] sd_buff_addr = 0;
    reg  [7:0]  sd_buff_dout = 0;
    reg         sd_buff_wr = 0;

    wire [7:0]  stream_data;
    wire        stream_valid;
    reg         busy = 1;          // hold streaming backpressure; nav only

    // reader <-> VM wires (exactly the emu.sv wiring)
    wire        jump_ack, pgc_loaded, pgc_error, menu_active, still_active;
    wire        seek_ack;
    wire [7:0]  cur_vts, best_menu_vts, cur_pgcn_rd, cur_cell, cell_count_w;
    wire [7:0]  auto_vts_w, cur_cell_cmdnr_w;
    wire        cell_ready, nav_ready_w;
    wire [6:0]  res_ttn_w;
    wire [7:0]  rd_next, rd_prev, rd_goup;
    wire        vm_cell_cmd_w, vm_pgc_end_w, vm_adv_w, vm_replay_w;
    wire        vm_jump_pulse;
    wire [1:0]  vm_jump_domain;
    wire [7:0]  vm_jump_vts, vm_jump_pgcn, vm_jump_cell, vm_jump_pgn;
    wire [9:0]  vm_jump_ptt;
    wire [3:0]  vm_jump_entry;
    wire [6:0]  vm_jump_ttn;
    wire        vm_seek_pulse;
    wire [7:0]  vm_seek_cell;
    wire        cmd_we_w, pm_we_w;
    wire [11:0] cmd_waddr_w;
    wire [7:0]  cmd_wdata_w, nr_pre_w, nr_post_w, nr_cell_w, nr_pgm_w;
    wire [6:0]  pm_waddr_w;
    wire [7:0]  pm_wdata_w;
    wire [7:0]  sprm_astn_w, sprm_spstn_w;
    wire [7:0]  vm_dbg;
    wire        keep_vbuf_w, vm_from_wait_w, nat_wait_w;

    reg         key_menu = 0, key_resume = 0, key_title = 0, key_return = 0;
    reg         vbuf_empty = 1;
    reg  [63:0] btn_cmd = 64'd0;
    reg         btn_cmd_valid = 0;

    dvd_iso_reader dut (
        .clk(clk), .rst_n(rst_n), .start(start), .file_size(file_size), .title_sel(4'd0), .vbuf_empty(vbuf_empty), .menu_snap(1'b0),
        .keep_vbuf(keep_vbuf_w),
        .jump_ttn(vm_jump_ttn), .jump_pgn(vm_jump_pgn), .jump_ptt(vm_jump_ptt),
        .vm_mode(1'b1), .vm_adv(vm_adv_w), .vm_replay(vm_replay_w),
        .vm_cell_cmd(vm_cell_cmd_w), .vm_pgc_end(vm_pgc_end_w),
        .nav_ready_o(nav_ready_w), .auto_vts(auto_vts_w),
        .cell_count_o(cell_count_w), .res_ttn(res_ttn_w),
        .pm_we(pm_we_w), .pm_waddr(pm_waddr_w), .pm_wdata(pm_wdata_w),
        .cmd_nr_pgm(nr_pgm_w),
        .seek_pulse(vm_seek_pulse), .seek_cell(vm_seek_cell), .seek_ack(seek_ack),
        .seek_natural(vm_seek_pulse & vm_from_wait_w),
        .jump_natural(vm_from_wait_w),
        .nat_wait_o(nat_wait_w),
        .cur_cell(cur_cell), .cell_ready(cell_ready),
        .jump_pulse(vm_jump_pulse), .jump_domain(vm_jump_domain),
        .jump_vts(vm_jump_vts), .jump_pgcn(vm_jump_pgcn),
        .jump_entry(vm_jump_entry), .jump_cell(vm_jump_cell),
        .jump_ack(jump_ack), .pgc_loaded(pgc_loaded), .pgc_error(pgc_error),
        .menu_active(menu_active), .still_active(still_active), .cur_vts(cur_vts),
        .cur_pgcn_o(cur_pgcn_rd),
        .best_menu_vts(best_menu_vts),
        .menu_btns_armed(1'b0),
        .cmd_we(cmd_we_w), .cmd_waddr(cmd_waddr_w), .cmd_wdata(cmd_wdata_w),
        .cmd_nr_pre(nr_pre_w), .cmd_nr_post(nr_post_w), .cmd_nr_cell(nr_cell_w),
        .cell_end_pulse(), .pgc_end_pulse(),
        .pgc_still_time(), .next_pgcn(rd_next), .prev_pgcn(rd_prev),
        .goup_pgcn(rd_goup),
        .cur_cell_still(), .cur_cell_cmdnr(cur_cell_cmdnr_w),
        .sd_lba(sd_lba), .sd_rd(sd_rd), .sd_ack(sd_ack),
        .sd_buff_addr(sd_buff_addr), .sd_buff_dout(sd_buff_dout), .sd_buff_wr(sd_buff_wr),
        .stream_data(stream_data), .stream_valid(stream_valid), .busy(busy),
        .pal_we(), .pal_waddr(), .pal_wdata(),
        .debug_active(), .debug_sd_rd(), .debug_sd_ack(), .debug_cache_has_data(),
        .debug_file_size(), .debug_total_sectors(), .debug_next_lba(),
        .debug_state(), .debug_iso_mode(), .debug_iso_error()
    );

    dvd_vm vm (
        .clk(clk), .rst_n(rst_n), .enable(1'b1), .start(start),
        .rnd_seed(16'hACE1), .sec_tick(1'b0),
        .entropy_stir(1'b0), .entropy_val(16'd0),
        .nav_ready(nav_ready_w), .auto_vts(auto_vts_w),
        .best_menu_vts(best_menu_vts), .res_ttn(res_ttn_w),
        .cmd_we(cmd_we_w), .cmd_waddr(cmd_waddr_w), .cmd_wdata(cmd_wdata_w),
        .nr_pre(nr_pre_w), .nr_post(nr_post_w), .nr_cell(nr_cell_w),
        .pm_we(pm_we_w), .pm_waddr(pm_waddr_w), .pm_wdata(pm_wdata_w),
        .nr_pgms(nr_pgm_w),
        .pgc_loaded(pgc_loaded), .pgc_error(pgc_error),
        .vm_cell_cmd(vm_cell_cmd_w), .cell_cmd_nr(cur_cell_cmdnr_w),
        .vm_pgc_end(vm_pgc_end_w), .menu_active(menu_active),
        .cur_vts(cur_vts), .cur_pgcn(cur_pgcn_rd), .cur_cell(cur_cell),
        .cell_count(cell_count_w),
        .next_pgcn(rd_next), .prev_pgcn(rd_prev), .goup_pgcn(rd_goup),
        .key_menu(key_menu), .key_resume(key_resume), .key_title(key_title), .key_return(key_return),
        .btn_cmd(btn_cmd), .btn_cmd_valid(btn_cmd_valid), .btn_sel(6'd1), .btns_armed(1'b0),
        .btn_force(), .btn_force_val(),
        .jump_pulse(vm_jump_pulse), .jump_domain(vm_jump_domain),
        .jump_vts(vm_jump_vts), .jump_pgcn(vm_jump_pgcn),
        .jump_entry(vm_jump_entry), .jump_ttn(vm_jump_ttn),
        .jump_pgn(vm_jump_pgn), .jump_cell(vm_jump_cell), .jump_ptt(vm_jump_ptt),
        .seek_pulse(vm_seek_pulse), .seek_cell(vm_seek_cell),
        .vm_replay(vm_replay_w), .vm_adv(vm_adv_w),
        .vm_from_wait(vm_from_wait_w), .wait_hold(nat_wait_w),
        .sprm_astn(sprm_astn_w), .sprm_spstn(sprm_spstn_w),
        .dbg_state(vm_dbg)
    );

    always #5 clk = ~clk;

    // ---- real metadata sectors (tools/cluedo_fixture.py) -------------------
    localparam N_META = 22;
    reg [7:0] meta [0:N_META*2048-1];
    initial $readmemh("bench/dvd/test_vobs/cluedo_menu_meta.hex", meta);

    function integer midx(input [31:0] s);
        begin
            case (s)
                32'd16: midx = 0; 32'd259: midx = 1; 32'd261: midx = 2;
                32'd262: midx = 3; 32'd263: midx = 4; 32'd264: midx = 5;
                32'd419: midx = 6; 32'd420: midx = 7; 32'd421: midx = 8;
                32'd422: midx = 9; 32'd423: midx = 10; 32'd424: midx = 11;
                32'd425: midx = 12; 32'd426: midx = 13; 32'd427: midx = 14;
                32'd428: midx = 15; 32'd13784: midx = 16; 32'd13786: midx = 17;
                32'd13787: midx = 18; 32'd13788: midx = 19; 32'd13789: midx = 20;
                32'd13790: midx = 21;
                default:   midx = -1;
            endcase
        end
    endfunction

    // mock HPS: one 512-byte block per sd_rd (ISO sector = sd_lba>>2)
    integer m = 0, bc = 0, lat = 0, mi;
    reg [31:0] rlba = 0;
    always @(posedge clk) begin
        sd_buff_wr <= 1'b0;
        case (m)
        0: begin sd_ack <= 1'b0; if (sd_rd) begin rlba <= sd_lba; lat <= 3; m <= 1; end end
        1: begin if (lat!=0) lat<=lat-1; else begin sd_ack<=1'b1; bc<=0; m<=2; end end
        2: begin
            sd_ack <= 1'b1; sd_buff_wr <= 1'b1; sd_buff_addr <= bc[13:0];
            mi = midx(rlba);
            if (mi >= 0) sd_buff_dout <= meta[mi*2048 + bc];
            else         sd_buff_dout <= 8'h00;
            bc <= bc + 1;
            if (bc == 2047) m <= 3;
        end
        3: begin sd_ack <= 1'b0; sd_buff_wr <= 1'b0; m <= 0; end
        endcase
    end

    // ---- PGC-load chain logger ---------------------------------------------
    integer errors = 0;
    integer loads = 0;
    reg [7:0] load_pgcn [0:31];
    reg       load_menu [0:31];
    always @(posedge clk) begin
        if (pgc_loaded && loads < 32) begin
            load_pgcn[loads] = cur_pgcn_rd;
            load_menu[loads] = menu_active;
            $display("  [load %0d] menu=%b vts=%0d pgcn=%0d cells=%0d nr_pre=%0d",
                     loads, menu_active, cur_vts, cur_pgcn_rd, cell_count_w, nr_pre_w);
            loads = loads + 1;
        end
        if (vm_jump_pulse)
            $display("  [jump] dom=%0d vts=%0d pgcn=%0d entry=%0d ttn=%0d",
                     vm_jump_domain, vm_jump_vts, vm_jump_pgcn, vm_jump_entry,
                     vm_jump_ttn);
        if (pgc_error)
            $display("  [pgc_error] fb walk");
    end

    task fail(input [511:0] msg);
        begin
            $display("FAIL: %0s", msg);
            errors = errors + 1;
        end
    endtask

    // wait until no pgc_loaded for `quiet` cycles or timeout
    task settle(input integer quiet, input integer timeout);
        integer q, t;
        begin
            q = 0; t = 0;
            while (q < quiet && t < timeout) begin
                @(posedge clk);
                t = t + 1;
                if (pgc_loaded) q = 0; else q = q + 1;
            end
        end
    endtask

    integer i, mark, saw_title_dom, saw_pgc2;
    initial begin
        @(negedge clk); rst_n = 1;
        repeat (4) @(negedge clk);
        start = 1; @(negedge clk); start = 0;   // start is level-sensitive: pulse

        // ---- boot: FP -> JumpTT 1 -> VTS1 PGC1 PRE -> CallSS VMGM pgc2 -----
        settle(60000, 4_000_000);
        if (loads == 0) fail("boot: no PGC ever loaded");
        else if (!(load_menu[loads-1] && load_pgcn[loads-1] == 8'd2))
            fail("boot: did not park on VMGM PGC2 (copyright)");
        $display("boot chain done: %0d loads, parked on pgcn=%0d menu=%b",
                 loads, load_pgcn[loads-1], load_menu[loads-1]);

        // ---- [A] MENU key = the AUTHORED restart trampoline ----------------
        // VTSM Root PGC1 {g5=0; JumpVTS_TT 1} -> title vts1/pgc1 -> CallSS
        // VMGM pgc2. Assert the chain ends back on the copyright (menu PGC2)
        // and passed through the title domain exactly as libdvdnav would.
        mark = loads;
        @(negedge clk); key_menu = 1;
        @(negedge clk); key_menu = 0;
        settle(80000, 8_000_000);
        saw_title_dom = 0;
        for (i = mark; i < loads; i = i + 1)
            if (!load_menu[i]) saw_title_dom = 1;
        if (loads == mark)
            fail("[A] menu key: no chain ran");
        else begin
            if (!(load_menu[loads-1] && load_pgcn[loads-1] == 8'd2))
                fail("[A] menu key: authored replay must end on VMGM PGC2 (copyright)");
            if (!saw_title_dom)
                fail("[A] menu key: replay must route through the title trampoline");
        end
        $display("[A] menu key = authored restart trampoline PASS-check done");

        // ---- [B] TITLE key = straight to the game menu ---------------------
        // VMGM Title (entry 2 = PGC1) -> LinkPGCN 12 -> PGC12 dispatcher ->
        // LinkPGCN 6 -> PGC6 (13-button game menu). No title-domain excursion,
        // no copyright (PGC2) reload.
        mark = loads;
        @(negedge clk); key_title = 1;
        @(negedge clk); key_title = 0;
        settle(80000, 8_000_000);
        saw_title_dom = 0; saw_pgc2 = 0;
        for (i = mark; i < loads; i = i + 1) begin
            if (!load_menu[i])                        saw_title_dom = 1;
            if (load_menu[i] && load_pgcn[i] == 8'd2) saw_pgc2 = 1;
        end
        if (loads == mark)
            fail("[B] title key: no chain ran");
        else begin
            if (!(load_menu[loads-1] && load_pgcn[loads-1] == 8'd6))
                fail("[B] title key: must land on VMGM PGC6 (the game menu)");
            if (saw_pgc2)
                fail("[B] title key: copyright (PGC2) must not replay");
            if (saw_title_dom)
                fail("[B] title key: unexpected title-domain excursion");
        end

        if (errors == 0)
            $display("ISO_READER_CLUEDO_MENU_TB: ALL TESTS PASSED");
        else begin
            $display("ISO_READER_CLUEDO_MENU_TB: %0d FAILURES", errors);
            $fatal(1);
        end
        $finish;
    end

    initial begin
        #200_000_000;
        $display("TIMEOUT");
        $fatal(1);
    end

endmodule
